style.css:
/* === Cute Pink Gradient Text (Roblox Stylish Theme) === */

body, 
span, 
a, 
p, 
div, 
h1, h2, h3, h4, h5, h6 {
    background: linear-gradient(90deg, #ffb7e6, #ff7ac6, #ff4fa5);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    font-weight: 700 !important;
    letter-spacing: 0.5px !important;
}

/* Soft glow effect */
body * {
    text-shadow: 0 0 4px rgba(255, 122, 198, 0.35) !important;
}

/* Hover sparkle for links */
a:hover {
    text-shadow: 0 0 8px rgba(255, 122, 198, 0.6) !important;
    transform: scale(1.03);
    transition: 0.15s ease;
}
